import Foundation

/// App UI catalog. Apply only to owned labels/status, never provider replies, user text or stored IDs.
public nonisolated enum CastorAppStrings {
    public static func label(_ source: String, language: SettingsDisplayLanguage) -> String {
        if let entry = entries[source] { return language == .japanese ? entry.japanese : entry.english }
        let repairSuffix = " LaMa underpaint was applied."
        if source.hasSuffix(repairSuffix) {
            return label(String(source.dropLast(repairSuffix.count)), language: language) + " "
                + label("LaMa underpaint was applied.", language: language)
        }
        if let boundary = source.range(of: " LaMa was unavailable for ") {
            return label(String(source[..<boundary.lowerBound]), language: language) + " "
                + label(String(source[source.index(after: boundary.lowerBound)...]), language: language)
        }
        for template in templates {
            let range = NSRange(source.startIndex..<source.endIndex, in: source)
            guard let match = template.pattern.firstMatch(in: source, range: range) else { continue }
            var values: [String] = []
            for index in 1..<match.numberOfRanges {
                guard let range = Range(match.range(at: index), in: source) else { continue }
                values.append(String(source[range]))
            }
            let target = language == .japanese ? template.japanese : template.english
            let pieces = target.components(separatedBy: "{value}")
            guard pieces.count == values.count + 1 else { return source }
            // A single pass preserves braces, percent signs and catalog-like text in inserted values.
            return zip(pieces.dropLast(), values).map { $0 + $1 }.joined() + (pieces.last ?? "")
        }
        return CastorSettingsStrings.label(source, language: language)
    }
    public static var sources: [String] { entries.keys.sorted() }
    private struct Entry: Sendable { let japanese: String; let english: String }
    private struct Template: @unchecked Sendable {
        let pattern: NSRegularExpression
        let japanese: String
        let english: String
    }
