    // Longest fixed portion first: an exact confidence label must win over a provider template.
    private static let templates: [Template] = [
        Template(pattern: try! NSRegularExpression(pattern: "^Arils rigging failed: (.*?)\\. Try Adjust Face, or enable Manual rigging in Settings › General › Advanced\\.$", options: .dotMatchesLineSeparators), japanese: "Arilsのリギングに失敗しました: {value}。「顔を調整」を試すか、設定 › 一般 › 詳細設定で手動リギングを有効にしてください。", english: "Arils rigging failed: {value}. Try Adjust Face, or enable Manual rigging in Settings › General › Advanced."),
        Template(pattern: try! NSRegularExpression(pattern: "^Arils rigging failed: (.*?)$", options: .dotMatchesLineSeparators), japanese: "Arilsのリギングに失敗しました: {value}", english: "Arils rigging failed: {value}"),
        Template(pattern: try! NSRegularExpression(pattern: "^LaMa was unavailable for ([0-9]+) view\\(s\\), so standard repair was used(.*?)\\.$"), japanese: "LaMaを利用できない画像が{value}枚あり、標準の補修を使いました{value}。", english: "LaMa was unavailable for {value} view(s), so standard repair was used{value}."),
